// Problem: Inventory deduction had race conditions
// Multiple users buying the last item simultaneously

@Service
public class OrderService {
    @Autowired
    private ProductRepository productRepo;

    @Transactional
    public Order createOrder(Long productId, int quantity) {
        // Before: simple read-modify-write caused overselling
        var product = productRepo.findById(productId)
            .orElseThrow();

        if (product.stock() < quantity) {
            throw new InsufficientStockException();
        }

        // Solution: pessimistic locking prevents concurrent modifications
        productRepo.decrementStockWithLock(productId, quantity);

        return new Order(productId, quantity);
    }
}

// In your interview answer:
// "I discovered the race condition through load testing with JMeter.
// Adding @Lock(PESSIMISTIC_WRITE) in JPA solved it, but increased 
// response time by 200ms under high load. Trade-off was acceptable."
