// PRESENTATION LAYER: Handles HTTP, delegates to services
@RestController
@RequestMapping("/api/orders")
public class OrderController {
    @Autowired
    private OrderService orderService;

    @PostMapping
    public ResponseEntity<OrderResponse> createOrder(@RequestBody OrderRequest req) {
        var order = orderService.processOrder(req);
        return ResponseEntity.status(201).body(new OrderResponse(order));
    }
}

// SERVICE LAYER: Business logic and transaction boundaries
@Service
public class OrderService {
    @Autowired
    private OrderRepository orderRepo;
    @Autowired
    private InventoryService inventoryService;

    @Transactional  // Ensures atomicity across multiple operations
    public Order processOrder(OrderRequest req) {
        inventoryService.reserveStock(req.productId(), req.quantity());
        var order = new Order(req.productId(), req.quantity());
        return orderRepo.save(order);
    }
}

// PERSISTENCE LAYER: Data access abstraction
@Repository
public interface OrderRepository extends JpaRepository<Order, Long> {
    List<Order> findByCustomerId(Long customerId);
}

// In your answer: "This separation lets me test business logic
// without starting a web server, and swap databases without
// touching controllers."
