// Situation: Users reported orders weren't saving, app returned 500 error
@Service
public class OrderService {
    private final OrderRepository orderRepo;
    private final InventoryService inventoryService;

    public Order createOrder(OrderRequest request) {
        var product = inventoryService.getProduct(request.productId());
        // BUG: product was null when productId didn't exist
        var order = new Order(
            product.getId(), // NPE thrown here!
            product.getPrice(),
            request.quantity()
        );
        return orderRepo.save(order);
    }
}

// Action: Reproduced by creating order with invalid productId
// Set breakpoint before product.getId(), inspected variables
// Found product was null—no null check!

// Fix: Added validation
var product = inventoryService.getProduct(request.productId());
if (product == null) {
    throw new ProductNotFoundException(request.productId());
}
// Result: Orders now fail gracefully with proper error message
